package br.radaraero.widget;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.view.View;import android.widget.*;import org.json.*;
public class RadarWidget extends AppWidgetProvider {
 static final String REFRESH="br.radaraero.widget.REFRESH";
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){drawAll(c,"Atualizando…");RefreshJob.schedule(c);}
 @Override public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,Bundle opts){drawAll(c,"");}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if(REFRESH.equals(i.getAction())){drawAll(c,"Atualizando…");RefreshJob.schedule(c);}}
 static void drawAll(Context c,String status){AppWidgetManager manager=AppWidgetManager.getInstance(c);int[] ids=manager.getAppWidgetIds(new ComponentName(c,RadarWidget.class));android.content.SharedPreferences prefs=c.getSharedPreferences("radar",0);
 for(int id:ids){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget);String stamp="Sem consulta · adsb.lol";JSONArray rows=new JSONArray();JSONObject point=new JSONObject();try{point=new JSONObject(prefs.getString("point","{}"));JSONObject snap=new JSONObject(prefs.getString("snapshot","{}"));rows=snap.optJSONArray("rows");if(rows==null)rows=new JSONArray();long at=snap.optLong("at",0);if(at>0)stamp="Consulta "+android.text.format.DateFormat.format("dd/MM HH:mm",at)+" · posições dessa consulta · adsb.lol";}catch(Exception ignored){}
 int[] rowIds={R.id.row1,R.id.row2,R.id.row3};for(int n=0;n<3;n++){JSONObject row=rows.optJSONObject(n);v.setTextViewText(rowIds[n],row==null?(n==0?(point.has("lat")?"Nenhum avião recente na última consulta":"Configure seu ponto salvo"):""):row.optString("label"));v.setViewVisibility(rowIds[n],n==0||row!=null?View.VISIBLE:View.GONE);}if(manager.getAppWidgetOptions(id).getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,180)<250){v.setViewVisibility(R.id.row2,View.GONE);v.setViewVisibility(R.id.row3,View.GONE);}v.setTextViewText(R.id.status,(status.isEmpty()?"":status+" · ")+stamp);
 Intent refresh=new Intent(c,RadarWidget.class).setAction(REFRESH);v.setOnClickPendingIntent(R.id.refresh,PendingIntent.getBroadcast(c,1,refresh,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));Intent cfg=new Intent(c,ConfigureActivity.class);cfg.putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);v.setOnClickPendingIntent(R.id.configure,PendingIntent.getActivity(c,id,cfg,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));
 Intent open=new Intent(c,ConfigureActivity.class);String link=point.optString("radarUrl","");if(link.startsWith("https://")){android.net.Uri u=android.net.Uri.parse(link);android.net.Uri.Builder b=u.buildUpon().clearQuery().appendQueryParameter("lat",point.optString("lat")).appendQueryParameter("lon",point.optString("lon")).appendQueryParameter("radiusKm",point.optString("radiusKm","10"));open=new Intent(Intent.ACTION_VIEW,b.build());}v.setOnClickPendingIntent(R.id.root,PendingIntent.getActivity(c,id+10000,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));manager.updateAppWidget(id,v);}}
}

